import{_ as r,o as i,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Bringing fscrypt Encryption to CephFS Userspace - Christopher Hoffman, IBM","description":"","frontmatter":{"title":"Bringing fscrypt Encryption to CephFS Userspace - Christopher Hoffman, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["FSCRYPT","CephFS","Encryption","Distributed Storage","User Space Implementation"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Bringing_fscrypt_Encryption_to_CephFS_Userspace_-_Christopher_Hoffman_IBM.md","filePath":"posts/2025/Bringing_fscrypt_Encryption_to_CephFS_Userspace_-_Christopher_Hoffman_IBM.md","lastUpdated":1780459816000}'),s={name:"posts/2025/Bringing_fscrypt_Encryption_to_CephFS_Userspace_-_Christopher_Hoffman_IBM.md"};function n(e,t,a,_,g,h){return i(),l("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要-将-fscrypt-引入-cephfs-用户空间" tabindex="-1">会议纪要：将 FSCRYPT 引入 CephFS 用户空间 <a class="header-anchor" href="#会议纪要-将-fscrypt-引入-cephfs-用户空间" aria-label="Permalink to &quot;会议纪要：将 FSCRYPT 引入 CephFS 用户空间&quot;">​</a></h3><p><strong>会议主题</strong>: 将 FSCRYPT（文件系统加密）引入 CephFS 用户空间<br><strong>主讲人</strong>: Christopher Hoffman, IBM 软件工程师<br><strong>日期</strong>: 未知<br><strong>时长</strong>: 未知</p><h4 id="_1-会议概述" tabindex="-1">1. <strong>会议概述</strong> <a class="header-anchor" href="#_1-会议概述" aria-label="Permalink to &quot;1. **会议概述**&quot;">​</a></h4><ul><li><strong>FSCRYPT</strong> 是一组内核库，支持透明文件系统加密，适用于多种文件系统，如 ext4、e2fs、Lustre 等。</li><li>会议重点讨论了如何将 FSCRYPT 从内核空间迁移到用户空间，以实现更广泛的分布式文件系统（如 Ceph）的加密应用。</li></ul><h4 id="_2-主要议题" tabindex="-1">2. <strong>主要议题</strong> <a class="header-anchor" href="#_2-主要议题" aria-label="Permalink to &quot;2. **主要议题**&quot;">​</a></h4><ul><li><strong>FSCRYPT 的工作原理</strong>： <ul><li>文件名和数据内容均被加密，支持多种加密算法，每个文件有自己的密钥，由主密钥派生。</li><li>文件名加密后存储为 Base64 编码，避免不可见字符问题。</li><li>加密操作可能带来性能开销，包括读写时的填充和数据块的正确性处理。</li></ul></li><li><strong>访问语义</strong>： <ul><li>支持锁定和解锁模式，锁定模式只能读取元数据，解锁模式可正常读写数据。</li></ul></li><li><strong>用户空间实现</strong>： <ul><li>目前用户空间对 FSCRYPT 的支持有限，主要通过 FUSE 实现，但存在数据损坏风险。</li></ul></li><li><strong>挑战</strong>： <ul><li>文件名显示、逻辑大小支持、访问语义实现等。</li></ul></li></ul><h4 id="_3-决定事项" tabindex="-1">3. <strong>决定事项</strong> <a class="header-anchor" href="#_3-决定事项" aria-label="Permalink to &quot;3. **决定事项**&quot;">​</a></h4><ul><li><strong>用户空间 FSCRYPT 的实现</strong>： <ul><li>核心功能已完成，包括加密/解密、FUSE 支持、CLI 工具、测试框架等。</li><li>需要进一步完善访问语义、多解锁支持、I/O 控制（ioctls）的正确性等问题。</li></ul></li><li><strong>测试与验证</strong>： <ul><li>通过多种工具进行元数据和数据路径的测试，验证了单客户端的稳定性。</li><li>正在进行多客户端的互操作性测试，特别是针对不同客户端的缓存行为和截断操作的验证。</li></ul></li></ul><h4 id="_4-后续行动计划" tabindex="-1">4. <strong>后续行动计划</strong> <a class="header-anchor" href="#_4-后续行动计划" aria-label="Permalink to &quot;4. **后续行动计划**&quot;">​</a></h4><ul><li><strong>完成用户空间实现的上游合并</strong>： <ul><li>完成剩余的 PR 工作，确保用户空间实现符合 FSCRYPT 规范。</li></ul></li><li><strong>性能测试</strong>： <ul><li>计划进行性能测试，评估 FSCRYPT 引入用户空间后的性能开销，并与内核客户端进行对比。</li></ul></li><li><strong>未来工作</strong>： <ul><li>支持加密文件系统的备份。</li><li>完善语义强制和性能优化。</li></ul></li></ul><h4 id="_5-问答环节" tabindex="-1">5. <strong>问答环节</strong> <a class="header-anchor" href="#_5-问答环节" aria-label="Permalink to &quot;5. **问答环节**&quot;">​</a></h4><ul><li><strong>问题1</strong>：关于写入时如何处理已有数据的问题，主讲人解释了读-修改-写的工作流程。</li><li><strong>问题2</strong>：关于性能测试的问题，主讲人表示性能测试尚未进行，但计划在未来进行。</li><li><strong>问题3</strong>：关于加密库的选择，主讲人表示使用的是标准的 C++ 加密库。</li></ul><h4 id="_6-总结" tabindex="-1">6. <strong>总结</strong> <a class="header-anchor" href="#_6-总结" aria-label="Permalink to &quot;6. **总结**&quot;">​</a></h4><ul><li>本次会议详细讨论了 FSCRYPT 在用户空间的实现进展、挑战和未来计划。主要目标是实现与内核空间的功能对等，并确保用户空间实现的稳定性和性能。</li></ul><p><strong>备注</strong>: 会议内容涉及较多技术细节，特别是关于 FSCRYPT 的工作原理和用户空间实现的挑战。后续工作将集中在性能测试和功能完善上。</p>',15)])])}const u=r(s,[["render",n]]);export{c as __pageData,u as default};
